+      bool finite = (actual_bits.bits & UINT64_C(0x7ff0000000000000)) !=
+                      UINT64_C(0x7ff0000000000000) &&
+                    (ref_bits.bits & UINT64_C(0x7ff0000000000000)) != UINT64_C(0x7ff0000000000000);
