"""Package the verified report without raw simulation or build artifacts."""
from pathlib import Path
import csv
import hashlib
import json
import shutil
import zipfile

root=Path(__file__).resolve().parent
report=root/'report'
out=root/'publication';out.mkdir(exist_ok=True)
expected={l.split('#')[0].strip().split('/')[-1] for l in (root/'candidate/gkeyll/ci/jenkins/expected_regression_diffs.txt').read_text().splitlines() if l.split('#')[0].strip()}
rows=list(csv.DictReader((report/'test-results.csv').open()))
assert {r['test'] for r in rows if r['mode']=='cpu_serial'}==expected
assert all(r['test'] in expected for r in rows)
sha={k:(root/(k+'-commit.txt')).read_text().strip() for k in ['baseline','candidate']}
for row in rows:
    section=report/row['mode']/row['test']
    assert json.loads((section/'complete.json').read_text())==sha
    assert (section/'comparisons.pdf').exists()
shutil.copy2(report/'pr1133-main-comparison.pdf',out/'pr1133-main-comparison.pdf')
with zipfile.ZipFile(out/'pr1133-per-test-pdfs.zip','w',zipfile.ZIP_DEFLATED) as archive:
    for row in rows:
        section=report/row['mode']/row['test']
        archive.write(section/'comparisons.pdf',row['mode']+'/'+row['test']+'.pdf')
with zipfile.ZipFile(out/'pr1133-report-data.zip','w',zipfile.ZIP_DEFLATED) as archive:
    for path in sorted(report.iterdir()):
        if path.is_file() and path.suffix in ['.csv','.json','.txt']:
            archive.write(path,'report/'+path.name)
    for name in ['compare.py','build-report.py','run-focused.py']:
        archive.write(root/name,'scripts/'+name)
    for label in ['baseline','candidate']:
        for name in ['recovery-unit-results.txt','recovery-unit-tests.log','source-verification.txt','focused-serial-regressions.log','focused-parallel-regressions.log']:
            path=root/label/name
            if path.exists():archive.write(path,label+'/'+name)
        archive.write(root/label/'gkeyll/config.mak',label+'/config.mak')
    for row in rows:
        section=report/row['mode']/row['test']
        for name in ['inventory.csv','quantity-index.csv','exceptions.txt']:
            archive.write(section/name,'sections/'+row['mode']+'/'+row['test']+'/'+name)
checks=[]
for path in sorted(out.glob('*')):
    if path.suffix in ['.pdf','.zip']:
        digest=hashlib.file_digest(path.open('rb'),'sha256').hexdigest()
        checks.append(digest+'  '+path.name)
(out/'SHA256SUMS.txt').write_text('\n'.join(checks)+'\n')
for path in sorted(out.iterdir()):print(path.name,path.stat().st_size)

