import json
from pathlib import Path
import re
import sys
import numpy as np
import postgkyl as pg

root=Path(__file__).resolve().parent
report=root/'report'
expected={l.split('#')[0].strip().split('/')[-1] for l in (root/'candidate/gkeyll/ci/jenkins/expected_regression_diffs.txt').read_text().splitlines() if l.split('#')[0].strip()}
signature={k:(root/(k+'-commit.txt')).read_text().strip() for k in ['baseline','candidate']}
signature['plot_script_sha256']=hashlib.sha256((root/'compare.py').read_bytes()).hexdigest()
issues=[];nonfinite=[];counts={};sections=[]
def quantity(name):
    return re.sub(r'_\d+$','',name[:-5])
for marker in sorted(report.glob('cpu_*/*/complete.json')):
    section=marker.parent;mode,test=section.parent.name,section.name
    if json.loads(marker.read_text())!=signature:
        issues.append(f'{mode}/{test}: stale renderer signature');continue
    sections.append((mode,test))
    if test not in expected:issues.append(f'Out-of-scope test: {test}')
    inventory=list(csv.DictReader((section/'inventory.csv').open()))
    plots=list(csv.DictReader((section/'quantity-index.csv').open()))
    fields=[r for r in inventory if 'metadata' not in r['status']]
    missing={quantity(r['file']) for r in fields}-{quantity(r['file']) for r in plots}
    issues.extend(f'{mode}/{test}: unplotted quantity {q}' for q in sorted(missing))
    for line in (section/'exceptions.txt').read_text().splitlines():
        if 'Error:' in line or 'plot failed' in line:issues.append(f'{mode}/{test}: {line}')
    components={}
    for row in plots:components.setdefault(row['file'],[]).extend(map(int,row['components'].split(';')))
    for name,comps in components.items():
        if comps!=list(range(max(comps)+1)):issues.append(f'{mode}/{test}/{name}: noncontiguous or duplicate components')
    counts[mode]=counts.get(mode,0)+1
    for row in inventory:
        if row['status']!='nonfinite values':continue
        record={'mode':mode,'test':test,'file':row['file']}
        for label,sub in [('baseline','creg-accepted'),('candidate','creg-runs')]:
            base=root/label/'gkylsoft/gkeyll-results'
            if mode=='cpu_parallel':base=base/'parallel-c-4'
            path=base/'gyrokinetic'/sub/mode/test/row['file']
            values=pg.load(path).values
            record[label+'_nonfinite']=int(np.sum(~np.isfinite(values)))
            record[label+'_coefficients']=int(values.size)
        nonfinite.append(record)
with (report/'nonfinite-data.csv').open('w') as out:
    writer=csv.DictWriter(out,fieldnames=['mode','test','file','baseline_nonfinite','baseline_coefficients','candidate_nonfinite','candidate_coefficients'])
    writer.writeheader();writer.writerows(nonfinite)
if '--partial' not in sys.argv:
    missing=expected-{test for mode,test in sections if mode=='cpu_serial'}
    issues.extend('Missing serial section: '+t for t in sorted(missing))
    if counts.get('cpu_parallel')!=9:issues.append('Expected nine MPI sections')
result={'sections':counts,'coverage_errors':issues,'nonfinite_files':len(nonfinite)}
(report/'coverage-audit.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result,indent=2))
raise SystemExit(bool(issues))

