names=['compare.py','build-report.py','watch-report.py','finalize-report.py']
targets={root+n for n in names}|{'.ci-comparison/pr1133/'+n for n in names}
procs={};selected=set()
for p in Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  args=p.joinpath('cmdline').read_bytes().decode().split('\0')
